"use strict";(self.webpackChunkintegrated_retail_kb=self.webpackChunkintegrated_retail_kb||[]).push([["742"],{8353(e,n,i){i.r(n),i.d(n,{metadata:()=>t,default:()=>p,frontMatter:()=>s,contentTitle:()=>o,toc:()=>c,assets:()=>l});var t=JSON.parse('{"id":"legal-policies/disaster-recovery-plan-61","title":"Disaster Recovery Plan","description":"Since disasters happen so rarely, disaster recovery planning is easily deferred. Having a contingency plan in place gives Integrated Retail Pte Ltd a\u2026","source":"@site/docs/legal-policies/disaster-recovery-plan-61.md","sourceDirName":"legal-policies","slug":"/legal-policies/disaster-recovery-plan","permalink":"/docs/legal-policies/disaster-recovery-plan","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"disaster-recovery-plan-61","title":"Disaster Recovery Plan","slug":"/legal-policies/disaster-recovery-plan","description":"Since disasters happen so rarely, disaster recovery planning is easily deferred. Having a contingency plan in place gives Integrated Retail Pte Ltd a\u2026"},"sidebar":"tutorialSidebar","previous":{"title":"Data Retention Policy","permalink":"/docs/legal-policies/data-retention-policy"},"next":{"title":"Environment Protection Policy","permalink":"/docs/legal-policies/environment-protection-policy"}}'),a=i(4848),r=i(8453);let s={id:"disaster-recovery-plan-61",title:"Disaster Recovery Plan",slug:"/legal-policies/disaster-recovery-plan",description:"Since disasters happen so rarely, disaster recovery planning is easily deferred. Having a contingency plan in place gives Integrated Retail Pte Ltd a\u2026"},o,l={},c=[{value:"1. Overview",id:"1-overview",level:2},{value:"2. Purpose",id:"2-purpose",level:2},{value:"3. Scope",id:"3-scope",level:2},{value:"4. Plan",id:"4-plan",level:2},{value:"4.1 Contingency Plans",id:"41-contingency-plans",level:3},{value:"4.2 Recovery Priorities",id:"42-recovery-priorities",level:3},{value:"5. Plan Compliance",id:"5-plan-compliance",level:2},{value:"5.1 Compliance Measurement",id:"51-compliance-measurement",level:3},{value:"5.2 Exceptions",id:"52-exceptions",level:3},{value:"5.3 Non-Compliance",id:"53-non-compliance",level:3}];function d(e){let n={h2:"h2",h3:"h3",li:"li",p:"p",ul:"ul",...(0,r.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(n.p,{children:"Disaster Recovery Plan"}),"\n",(0,a.jsx)(n.p,{children:"Last update: 13 August 2026"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.p,{children:"\xa0"}),"\n",(0,a.jsx)(n.h2,{id:"1-overview",children:"1. Overview"}),"\n",(0,a.jsx)(n.p,{children:"Since disasters happen so rarely, disaster recovery planning is easily deferred. Having a contingency plan in place gives Integrated Retail Pte Ltd a competitive advantage, particularly with enterprise customers who require evidence of a documented recovery capability before awarding business."}),"\n",(0,a.jsx)(n.p,{children:"Integrated Retail supplies, deploys and supports a range of IT solutions across Singapore, Malaysia, Thailand and Indonesia. Customers contract with the Company and look to the Company first when service is disrupted, regardless of whether the underlying cause lies with the Company, an upstream vendor, a customer site or a third-party carrier. The Company therefore maintains its own recovery capability rather than relying solely on the arrangements of the vendors whose products it supplies."}),"\n",(0,a.jsx)(n.p,{children:"Disasters are not limited to adverse weather conditions. Any event that could cause an extended delay of service should be considered, including cyber incidents, loss of premises, carrier or hosted-platform outages, supply chain disruption, and loss of key personnel. This plan forms part of the Company's Business Continuity Plan, and operates alongside the disaster recovery requirements of the Company's principal vendors."}),"\n",(0,a.jsx)(n.h2,{id:"2-purpose",children:"2. Purpose"}),"\n",(0,a.jsx)(n.p,{children:"This plan describes the process by which Integrated Retail Pte Ltd will recover the IT systems, applications, data and field service capability required to deliver and support its solutions following any type of disaster that causes a major outage."}),"\n",(0,a.jsx)(n.p,{children:"The plan is deliberately solution-independent. It applies uniformly across the Company's portfolio, so that the addition or withdrawal of a solution does not require the plan to be rewritten."}),"\n",(0,a.jsx)(n.h2,{id:"3-scope",children:"3. Scope"}),"\n",(0,a.jsx)(n.p,{children:"This plan applies to all Integrated Retail employees, contractors and appointed in-country service partners involved in the sale, deployment or support of Company solutions. It covers Company IT systems and business applications, customer-facing services delivered by the Company, hardware and spare parts inventory, data held on behalf of customers, and Company premises."}),"\n",(0,a.jsx)(n.p,{children:"The following are outside the scope of this plan:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"The internal recovery arrangements of vendors for platforms they host. These remain the vendor's responsibility; this plan defines the Company's escalation route and customer-facing response."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Customer-owned infrastructure, including site networks, connectivity and electrical supply, except where the Company has contracted to manage it."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Life safety and evacuation, which are governed by local emergency procedures and always take precedence over recovery activity."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.p,{children:"Accountability for developing, testing and maintaining this plan sits with IT Management, who must ensure it is kept up to date. Country Managers are accountable for the accuracy of local arrangements."}),"\n",(0,a.jsx)(n.h2,{id:"4-plan",children:"4. Plan"}),"\n",(0,a.jsx)(n.h3,{id:"41-contingency-plans",children:"4.1 Contingency Plans"}),"\n",(0,a.jsx)(n.p,{children:"The following contingency plans are maintained by Integrated Retail and apply to every solution in the portfolio:"}),"\n",(0,a.jsxs)(n.ul,{children:["\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Computer Emergency Response Plan: Who is to be contacted, when and how, and what immediate actions must be taken. Any employee aware of a potential disaster reports it immediately to the Technical Services Manager. Only the DR Coordinator, or the Managing Director in their absence, may formally declare a disaster and activate this plan. Life safety is confirmed first; a suspected cyber incident is contained before recovery is attempted; and an incident log is opened and maintained throughout."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Succession Plan: Every recovery role has a named primary and at least one named alternate. Authority passes automatically to the alternate if the primary cannot be contacted within 30 minutes. At least two people per country are trained to install and diagnose each solution the Company supports in that market, and administrative credentials are held in the Company password vault with break-glass access for more than one person."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Data Study: Customer operational data, site and device configuration, licence and asset records, contracts and account data are recorded in the Company data inventory with their criticality and confidentiality classification. Personal data held by the Company as controller is limited to named user accounts and employee records. Personal data held on behalf of customers \u2014 which may include customer, loyalty, transaction and workforce records depending on the solution deployed \u2014 is classified as Restricted and recorded in the data inventory against the relevant customer environment. Any deployment capturing video, images or other sensitive data is separately registered and treated as high sensitivity."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Criticality of Service List: Services are ranked in three tiers and recovered in the order set out in Section 4.2, in both short-term and long-term timeframes."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Data Backup and Restoration Plan: All critical data is backed up daily to encrypted storage, with one copy held off-site in a separate location and one copy immutable or offline. Backups are retained for 12 months and a restoration test is performed quarterly. Where a solution buffers data locally on field devices during a loss of connectivity, any outage approaching half of that buffer window is escalated as critical."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Equipment Replacement Plan: A regional spare pool is held in Malaysia, with a secondary store in Singapore and local buffer stock in Thailand and Indonesia. Replacement priority is field devices, then network and power equipment, then connectivity hardware, then server hardware, then engineer field kits. Equipment is sourced first from the spare pool, then from the vendor, then from approved local distributors. A pre-qualified customs broker is retained in each country."}),"\n"]}),"\n",(0,a.jsxs)(n.li,{children:["\n",(0,a.jsx)(n.p,{children:"Mass Media Management: The Managing Director is the sole authorised spokesperson to media, and the Customer Communications Lead is the sole authorised channel to customers. No other employee or partner may comment on an incident, including on personal social media. Communications may confirm the services and regions affected, current status and the next update time. They must not disclose customer names, unremediated vulnerabilities, speculation as to cause, or any statement on liability."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(n.h3,{id:"42-recovery-priorities",children:"4.2 Recovery Priorities"}),"\n",(0,a.jsx)(n.p,{children:"Services are recovered in the following order. Recovery Time Objective (RTO) is the maximum acceptable time to restore service; Recovery Point Objective (RPO) is the maximum acceptable data loss. Where a recovery objective depends on a vendor-hosted platform, the committed figure is that stated in the applicable vendor Service Level Agreement, and the Company's commitment to its customers is set out in the relevant customer contract."}),"\n",(0,a.jsx)(n.p,{children:"Tier"}),"\n",(0,a.jsx)(n.p,{children:"Service Category"}),"\n",(0,a.jsx)(n.p,{children:"RTO"}),"\n",(0,a.jsx)(n.p,{children:"RPO"}),"\n",(0,a.jsx)(n.p,{children:"1"}),"\n",(0,a.jsx)(n.p,{children:"Data capture and processing at customer sites"}),"\n",(0,a.jsx)(n.p,{children:"4 hours"}),"\n",(0,a.jsx)(n.p,{children:"Nil where the solution buffers locally"}),"\n",(0,a.jsx)(n.p,{children:"1"}),"\n",(0,a.jsx)(n.p,{children:"Vendor-hosted customer platforms"}),"\n",(0,a.jsx)(n.p,{children:"Per vendor SLA"}),"\n",(0,a.jsx)(n.p,{children:"Per vendor SLA"}),"\n",(0,a.jsx)(n.p,{children:"1"}),"\n",(0,a.jsx)(n.p,{children:"Company-hosted or on-premise customer systems"}),"\n",(0,a.jsx)(n.p,{children:"8 hours"}),"\n",(0,a.jsx)(n.p,{children:"24 hours"}),"\n",(0,a.jsx)(n.p,{children:"1"}),"\n",(0,a.jsx)(n.p,{children:"Connectivity and data upload path, where Company-supplied"}),"\n",(0,a.jsx)(n.p,{children:"8 hours"}),"\n",(0,a.jsx)(n.p,{children:"Nil where the solution buffers locally"}),"\n",(0,a.jsx)(n.p,{children:"1"}),"\n",(0,a.jsx)(n.p,{children:"Customer helpdesk, ticketing and email"}),"\n",(0,a.jsx)(n.p,{children:"8 hours"}),"\n",(0,a.jsx)(n.p,{children:"4 hours"}),"\n",(0,a.jsx)(n.p,{children:"2"}),"\n",(0,a.jsx)(n.p,{children:"Remote support access, licence and asset records"}),"\n",(0,a.jsx)(n.p,{children:"24 hours"}),"\n",(0,a.jsx)(n.p,{children:"24 hours"}),"\n",(0,a.jsx)(n.p,{children:"2"}),"\n",(0,a.jsx)(n.p,{children:"CRM, contracts, spare parts and finance systems"}),"\n",(0,a.jsx)(n.p,{children:"48 hours"}),"\n",(0,a.jsx)(n.p,{children:"24 hours"}),"\n",(0,a.jsx)(n.p,{children:"3"}),"\n",(0,a.jsx)(n.p,{children:"Scheduling tools, website, HR and internal systems"}),"\n",(0,a.jsx)(n.p,{children:"5 working days"}),"\n",(0,a.jsx)(n.p,{children:"7 days"}),"\n",(0,a.jsx)(n.p,{children:"In the short term (0\u201324 hours) the Company confirms staff safety, contains the incident, verifies backup integrity, restores Tier 1 services and notifies affected customers. In the longer term (24 hours to 30 days) the Company restores Tier 2 and Tier 3 services, reconciles any data gap across the outage window, replaces damaged equipment, returns to normal production configuration and completes a post-incident review."}),"\n",(0,a.jsx)(n.p,{children:"Once the plans above are in place, they must be practised to the extent possible. Management sets aside time to test implementation, so that weaknesses which would cause the plan to fail are found and corrected in conditions that carry few consequences. A tabletop exercise is held annually with the recovery team, using a different scenario and a different solution each year. A backup restoration test is performed quarterly and the result logged whether it passes or fails. Emergency contact details are verified quarterly, with a notification test twice yearly. Following any invocation of this plan, a post-incident review is completed within ten working days."}),"\n",(0,a.jsx)(n.p,{children:"The plan, at a minimum, will be reviewed and updated on an annual basis, and also after any invocation, any change to the recovery team, any addition of a solution to the portfolio, and any material change to the countries of operation. Current copies are held online, in print at each country office, and on offline media, so that the plan remains available when Company systems are not."}),"\n",(0,a.jsx)(n.h2,{id:"5-plan-compliance",children:"5. Plan Compliance"}),"\n",(0,a.jsx)(n.h3,{id:"51-compliance-measurement",children:"5.1 Compliance Measurement"}),"\n",(0,a.jsx)(n.p,{children:"IT Management will verify compliance to this plan through various methods, including but not limited to business tool reports, evidence of completed test exercises, internal and external audits, and feedback to the plan owner. Evidence of testing is retained for a minimum of three years."}),"\n",(0,a.jsx)(n.h3,{id:"52-exceptions",children:"5.2 Exceptions"}),"\n",(0,a.jsx)(n.p,{children:"Any exception to this plan must be approved by IT Management in advance, recorded with a business justification and a compensating control, and re-approved at each annual review."}),"\n",(0,a.jsx)(n.h3,{id:"53-non-compliance",children:"5.3 Non-Compliance"}),"\n",(0,a.jsx)(n.p,{children:"An employee found to have violated this plan may be subject to disciplinary action, up to and including termination of employment. Appointed partners found in violation may have their appointment suspended or terminated."}),"\n",(0,a.jsx)(n.p,{children:"\xa0"})]})}function p(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,a.jsx)(n,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,n,i){i.d(n,{R:()=>s,x:()=>o});var t=i(6540);let a={},r=t.createContext(a);function s(e){let n=t.useContext(r);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:s(e.components),t.createElement(r.Provider,{value:n},e.children)}}}]);